def solve(inputs: dict) -> float:
    matrix = inputs.get('matrix', [[9, 26], [13, 16]])
    power = inputs.get('power', 37)
    modulus = inputs.get('modulus', 370583)

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, n, mod):
        """Compute M^n modulo mod using fast exponentiation"""
        if n == 1:
            return [[M[i][j] % mod for j in range(2)] for i in range(2)]

        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [[M[i][j] % mod for j in range(2)] for i in range(2)]

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result_matrix = matrix_pow(matrix, power, modulus)

    # Sum all entries
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return float(total % modulus)

